mapper.select:
SELECT event_id, attempt_id, actor_id, trace_id, action_code, stage_code, resource_id, business_no,
       version_no, activation_sequence, before_state, after_state, reason_code, chain_audit_id,
       original_event_id, observed_at, recorded_at
FROM mk_release_operation_audit
WHERE tenant_id = #{tenant} AND campaign_id = #{campaignId} AND organization_id = #{organizationId}
  AND shop_id <=> #{shopId} AND action_code != 'release.audit.read'
 AND event_id < #{before} 
ORDER BY event_id DESC LIMIT #{limit}
